@media(max-width:700px){.huwabc-score .huwabc-audio{padding:6px 8px}.huwabc-score .huwabc-audio-controls .abcjs-inline-audio .abcjs-btn{padding:4px 7px;font-size:10px}.huwabc-score .huwabc-audio-controls .abcjs-tempo-wrapper{gap:2px}}
/* Our full ABC EditTemplate: a proper music editor, not the generic technical fields table. */
