.huwabc-full-edit .huwabc-code-label{display:flex;align-items:center;justify-content:space-between;gap:9px;flex-wrap:wrap;}
@media(max-width:1100px){.huwabc-full-edit .huwabc-form-grid{grid-template-columns:repeat(2,minmax(0,1fr));}.huwabc-full-edit .huwabc-edit-layout{grid-template-columns:minmax(0,1fr);}}
