 display:grid;
 grid-template-columns:repeat(3,minmax(0,1fr)) 4.8em;
 grid-template-areas:"loop restart play stop" "progress progress progress clock";
 align-items:center;
 gap:8px 6px;
 width:100%;
 min-width:0;
 min-height:32px;
 height:auto;
 margin:0;
 padding:0;
 font-size:11px;
 box-sizing:border-box;
}
