.huwabc-score .huwabc-audio-controls .abcjs-inline-audio .abcjs-btn,
.huwabc-score .huwabc-audio-controls .abcjs-inline-audio .huwabc-stop {
 width:100%;
 min-width:0;
 height:32px;
 min-height:32px;
 margin:0;
 padding:4px 6px;
 box-sizing:border-box;
 white-space:nowrap;
 font-size:11px;
}
.huwabc-score .huwabc-audio-controls .abcjs-midi-progress-background {
 grid-area:progress;
 min-width:0;
 width:calc(100% - 14px);
 margin:0 7px;
}
.huwabc-score .huwabc-audio-controls .abcjs-midi-clock {
 grid-area:clock;
 display:block;
 min-width:0;
 width:100%;
 margin:0;
 text-align:center;
 white-space:nowrap;
 font-variant-numeric:tabular-nums;
}
.huwabc-score .huwabc-audio-controls .huwabc-tempo-modes {
 display:grid;
 grid-template-columns:max-content max-content 70px minmax(0,1fr);
 align-items:center;
 gap:6px 8px;
 width:100%;
 min-width:0;
 margin:0;
 font-size:12px;
}
.huwabc-score .huwabc-audio-controls .huwabc-tempo-modes > button,
.huwabc-score .huwabc-audio-controls .huwabc-tempo-modes > select {
 height:32px;
 min-height:32px;
 margin:0;
 padding:4px 10px;
 box-sizing:border-box;
 white-space:nowrap;
}
.huwabc-score .huwabc-audio-controls .huwabc-tempo-status {
 grid-column:1 / -1;
 min-width:0;
 line-height:1.5;
 min-height:1.5em;
 white-space:nowrap;
 font-variant-numeric:tabular-nums;
}
/* Text-only transport buttons on very narrow embedded/phone layouts. */
@container huwabc-player (max-width:300px) {
 .huwabc-score .huwabc-audio-controls .abcjs-inline-audio .huwabc-icon {display:none!important}
}
@container huwabc-player (min-width:400px) {
 .huwabc-score .huwabc-audio-controls .huwabc-tempo-status {grid-column:4;grid-row:1}
}
@container huwabc-player (min-width:540px) {
 .huwabc-score .huwabc-audio-controls .abcjs-inline-audio {
  grid-template-columns:7.5em 7.5em 7.5em minmax(0,1fr) 7ch 4.8em;
  grid-template-areas:"loop restart play progress clock stop";
 }
}
@media (pointer:coarse) {
 .huwabc-score .huwabc-audio-controls .abcjs-inline-audio .abcjs-btn,
 .huwabc-score .huwabc-audio-controls .abcjs-inline-audio .huwabc-stop,
 .huwabc-score .huwabc-audio-controls .huwabc-tempo-modes > button,
 .huwabc-score .huwabc-audio-controls .huwabc-tempo-modes > select {height:40px;min-height:40px}
}

/* A discoverable, stable transport shortcut; no extra toolbar button. */
.huwabc-score .huwabc-transport-keyhint{display:block;grid-column:1 / -1;order:3;font:10px/1.4 system-ui;color:#587366;min-height:14px;white-space:nowrap;padding:0 1px}

.huwabc-voice-name-grid{display:grid;gap:10px;margin:10px 0}.huwabc-voice-name-row{display:grid;grid-template-columns:3.5em minmax(100px,1fr) minmax(90px,.7fr);gap:8px;align-items:end}.huwabc-voice-name-row>strong{font:600 12px system-ui;align-self:center;overflow-wrap:anywhere}.huwabc-voice-names .huwabc-muted{margin:8px 0}.huwabc-voice-names .huwabc-input{min-width:0}

/* 0.3.26-test.1 · Persistent source location for every floating-editor target.
   The transparent textarea remains the ONLY editable ABC field. */
.huwabc-source-editor pre .huwabc-source-match{
  background:rgba(249,194,64,.52);color:#183b34!important;
  box-shadow:inset 0 -2px 0 #bd8220;
  border-radius:2px;
}
.huwabc-source-editor pre .huwabc-source-match .abc-code-header,
.huwabc-source-editor pre .huwabc-source-match .abc-code-note,
.huwabc-source-editor pre .huwabc-source-match .abc-code-chord,
.huwabc-source-editor pre .huwabc-source-match .abc-code-lyric{color:#183b34!important;}
.huwabc-source-editor pre .huwabc-source-insertion{
 display:inline-block;width:0;height:1em;overflow:visible;
 border-left:2px solid #c27c06;margin-right:-2px;
 vertical-align:-.15em;
}
/* Native selection remains possible while typing; it does not replace the persistent mark. */
.huwabc-source-editor textarea.huwabc-code::selection{background:rgba(56,139,111,.20);color:transparent;}

/* Concert-pitch audio and selectable written-pitch notation (v0.3.28). */
.huwabc-instrument-bar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;padding:9px 16px;background:#f4f8f6;border-bottom:1px solid #dde8e3}
.huwabc-instrument-group{display:flex;flex-wrap:wrap;align-items:center;gap:10px;min-width:0}
.huwabc-instrument-legend{color:#315b51;font-weight:700;font-size:12px}
.huwabc-instrument-buttons{display:inline-flex;gap:0;border:1px solid #a4c6b8;border-radius:10px;overflow:hidden;background:white;flex:none}
.huwabc-instrument-option{font:700 13px/1.3 system-ui,sans-serif;min-width:48px;min-height:40px;padding:8px 12px;color:#24544c;background:#fff;border:0;border-right:1px solid #bdd8ce;cursor:pointer}
.huwabc-instrument-option:last-child{border-right:0}
.huwabc-instrument-option[aria-pressed=true]{background:#256e5d;color:white}
.huwabc-instrument-option:focus-visible{outline:3px solid #47b2a5;outline-offset:-3px;position:relative;z-index:1}
.huwabc-instrument-hint{font-size:11px;color:#56746d}
.huwabc-instrument-print{margin-left:auto;min-height:40px}
.huwabc-instrument-bar-compact{padding:8px 11px}
@media(max-width:600px){.huwabc-instrument-bar{padding:8px}.huwabc-instrument-group{gap:6px}.huwabc-instrument-option{min-width:42px;min-height:40px;padding:7px 10px}.huwabc-instrument-hint{flex-basis:100%}}

/* Jazz type extends to the native tiddler heading only when this tiddler has
   an ABC notation player with the jazz setting. Buttons/toolbars stay legible. */
.tc-tiddler-frame:has(.huwabc-score.huwabc-jazz-font) .tc-titlebar h2{
 font-family:PetalumaScript,Georgia,serif!important;
 font-weight:400!important;letter-spacing:0!important;
}

/* One mixer opening exposes written voices first and optional backing channels below. */
.huwabc-score .huwabc-mixer[hidden]{display:none!important;}
.huwabc-score .huwabc-mixer-voices{grid-column:1 / -1;min-width:0;container-type:inline-size;}
.huwabc-score .huwabc-accomp-channels{grid-column:1 / -1;min-width:0;margin-top:3px;border-top:1px solid #dae7df;}
.huwabc-score .huwabc-accomp-channels>summary{cursor:pointer;padding:9px 3px 5px;font-size:12px;font-weight:650;}
.huwabc-score .huwabc-accomp-channels-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(142px,1fr));gap:8px;margin:5px 0 8px;}
@media(max-width:600px){.huwabc-score .huwabc-accomp-channels-grid{grid-template-columns:repeat(2,minmax(0,1fr));}}

/* 0.3.35: unobtrusive manual sound engine chooser */
.huwabc-audio-troubleshooting .huwabc-engine-summary{font-size:11px;font-weight:400;opacity:.78}
.huwabc-engine-row{display:flex;align-items:center;gap:12px;justify-content:space-between;flex-wrap:wrap;margin:9px 0 4px;font:12px system-ui,sans-serif}
.huwabc-engine-row>span{font-weight:650}
.huwabc-engine-select{font:12px system-ui,sans-serif;max-width:min(100%,300px);min-height:30px;padding:3px 8px;border:1px solid #bdd8c8;border-radius:7px;background:#fff;color:#245647}
.huwabc-engine-explanation{font-size:11px;max-width:640px;line-height:1.45;margin:5px 0}
.huwabc-audio-troubleshooting>.huwabc-sound-state{margin:6px 0}
