      var graces=digits.filter(function(ch){return ch.isGrace;});
      if(graces.length===graceEvents.length)graces.forEach(function(ch,i){place(graceEvents[i],[ch]);});
      place(ev,digits.filter(function(ch){return !ch.isGrace;}));
