(function(){
'use strict';
var INDEX='https://raw.githubusercontent.com/stewing-co/jambuddy-abc/main/index/search/balkan.json';
var BASE='https://raw.githubusercontent.com/stewing-co/jambuddy-abc/main/sources/';
var CACHE=null;
function normalize(text){return String(text||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();}
function safeURL(url){return typeof url==='string'&&url.startsWith(BASE)&&!/[?#]/.test(url);}
async function download(url,encoding){
 var ctrl=new AbortController(),timer=setTimeout(function(){ctrl.abort();},18000);
 try{
  var r=await fetch(url,{mode:'cors',signal:ctrl.signal,cache:'default'});
  if(!r.ok)throw Error('Arkivet svarede HTTP '+r.status+'.');
  var data=await r.arrayBuffer();
  if(data.byteLength>6000000)throw Error('Kildefilen er for stor til direkte import (over 6 MB).');
  return new TextDecoder(encoding||'utf-8',{fatal:false}).decode(data);
 }finally{clearTimeout(timer);}
}
async function list(){
 if(CACHE)return CACHE;
 CACHE=download(INDEX).then(function(text){
  var parsed=JSON.parse(text);
  if(parsed.version!==1||parsed.genre!=='balkan'||!Array.isArray(parsed.tunes))throw Error('Balkanindekset har et ukendt format.');
  return parsed.tunes.filter(function(t){return t&&safeURL(t.url)&&Array.isArray(t.titles)&&t.titles.length;});
 }).catch(function(err){CACHE=null;throw err;});
 return CACHE;
}
function filter(all,q){var term=normalize(q);if(!term)return all;return all.filter(function(t){return [t.titles.join(' '),t.category||'',t.key||'',t.meter||''].some(function(s){return normalize(s).includes(term);});});}
async function fetchTune(item){
 if(!item||!safeURL(item.url))throw Error('Ukendt kildeadresse til Balkanmelodien.');
 var raw=await download(item.url,item.encoding||'utf-8');
 // A source file can contain hundreds of tunes. Copy only the selected X: section.
 var lines=[],re=/^X:\s*([^\r\n]*)/gm,match;
 while((match=re.exec(raw))!==null)lines.push({index:match.index,x:match[1].trim()});
 if(!lines.length)throw Error('Kildefilen indeholder ingen ABC-melodier med X:.');
 function chunk(i){return raw.slice(lines[i].index,i+1<lines.length?lines[i+1].index:raw.length).trim();}
 var ordinal=Number(item.ordinal),matches=[];
 for(var i=0;i<lines.length;i++)if(lines[i].x===String(item.x))matches.push(i);
 if(matches.length>1){
  var title=normalize(item.titles[0]);
  matches.sort(function(a,b){return Number(!chunk(a).split('\n').some(function(line){return /^T:/.test(line)&&normalize(line.slice(2))===title;}))-Number(!chunk(b).split('\n').some(function(line){return /^T:/.test(line)&&normalize(line.slice(2))===title;}));});
 }
 var selected=matches.length?matches[0]:(Number.isInteger(ordinal)&&ordinal>=0&&ordinal<lines.length?ordinal:-1);
 if(selected<0)throw Error('Kunne ikke matche melodien i arkivfilen.');
 var source=chunk(selected);
 if(!/^K:\s*\S/m.test(source))throw Error('Den valgte melodi mangler toneartsfeltet K:.');
 return source;
}
exports.list=list;exports.filter=filter;exports.fetchTune=fetchTune;exports.indexUrl=INDEX;
})();"},"$:/plugins/huwiki/abc/balkan7.js":{"title":"$:/plugins/huwiki/abc/balkan7.js","type":"application/javascript","module-type":"library","text":"/*\
