(function(){'use strict';
function isiPad(){return /iPad|iPhone|iPod/.test(navigator.userAgent)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1;}
function nativeFile(html,name){return new File([html],name,{type:'text/html'});}
function fallback(html,name,onStatus,options){
 var english=options&&options.language==='en';
 var old=document.getElementById('huwabc-site-share-fallback');if(old)old.remove();
 var overlay=document.createElement('div');overlay.id='huwabc-site-share-fallback';overlay.style.cssText='position:fixed;inset:0;z-index:30000;background:#142b2466;display:grid;place-items:center;padding:15px';
 var panel=document.createElement('div');panel.style.cssText='width:min(620px,98vw);background:white;color:#19362e;border-radius:16px;padding:18px;box-shadow:0 25px 60px #0003';
 var heading=document.createElement('h3');heading.textContent=english?'Save the Site player':'Gem Site-afspilleren';panel.appendChild(heading);
 var hint=document.createElement('p');hint.textContent=english?'This browser cannot share HTML files. Open the wiki in Safari and select Download HTML, or copy this code and save it as '+name+' on a computer.':'Denne browser tilbyder ikke deling af HTML-filer. Åbn wikien i Safari, og vælg Hent HTML, eller kopiér HTML-koden her og gem den som '+name+' på en computer.';panel.appendChild(hint);
