          ensureOpen(options);
          stats.pcmBytes = groups.size * frameCount * 2 * 4;
          stats.renderMs = now() - startTime;
          stats.heapBytes = heapSize();
          stats.maxSliceMs = Math.max(maxSliceMs, now() - sliceStart);
          stats.parts = summaries;
