        } catch (error) {
          stats.cancelled = error && error.name === 'AbortError';
          stats.renderMs = now() - startTime;
          stats.maxSliceMs = Math.max(maxSliceMs, now() - sliceStart);
          stats.pcmBytes = 0;
          stats.parts = [];
          throw error;
        } finally {
          if (!closed) clean();
        }
      }
      function render(notes, durationSeconds, audioContext, options) {
        // Serialize jobs because every render uses the same synth and font.
        // Each queued job checks cancellation again when it reaches the front.
        const job = queue.catch(() => {}).then(async () => {
          busy = true;
          try { return await runRender(notes, durationSeconds, audioContext, options || {}); }
          finally { busy = false; }
        });
        queue = job;
        return job;
      }
      function audition(notes, audioContext, options) {
        options = options || {};
        const duration = Number.isFinite(options.durationSeconds) ? options.durationSeconds : Math.max(0.05, ...notes.map(note => Number(note.end) || 0)) + 2;
        return render(notes, duration, audioContext, options);
      }
