        if (event.el_type !== 'note') return;
        if (event.startTriplet) multiplier = Number(event.tripletMultiplier) || 1;
        var duration = Number(event.duration) * multiplier;
        if (!Number.isFinite(duration) || duration <= 0) {
          if (event.endTriplet) multiplier = 1;
          return;
        }
        if (!active) active = {
          meter: copyMeter(meter), notes: [], duration: 0,
          sourceStart: Number.isFinite(event.startChar) ? event.startChar : null
