        active.notes.push({ event: event, offset: active.duration, duration: duration });
        active.duration += duration;
        if (event.endTriplet) multiplier = 1;
      });
    });
    flush();
    if (tempoChange) warn('Akkompagnement ved temposkift er endnu ikke understøttet.');

    var played = [];
    written.forEach(function (measure) {
      var anchor = measure.notes.find(function (item) { return occurrences(item.event).length > 0; });
      if (!anchor) {
        // A written ending may legitimately never be played by ABCJS. Preserve
        // that omission instead of fabricating a position on a fixed grid.
        warn('En noteret takt havde ingen afspilningstid og blev udeladt af akkompagnementet.');
