        measure.notes[0].event.rest.type === 'multimeasure' ? Number(measure.notes[0].event.rest.text) : 1;
      if (!Number.isInteger(count) || count < 1 || count > 10000) count = 1;
      var unitDuration = measure.duration / count;
      occurrences(anchor.event).forEach(function (when) {
