      inventory.forEach(function (other) {
        if (!other.notes || other.staff === selected.staff && other.voice === selected.voice) return;
        var last = 0, triplet = 1;
        (parsedTune.lines || []).forEach(function (line) {
          var staff = (line.staff || [])[other.staff];
          var voice = staff && (staff.voices || [])[other.voice];
          (voice || []).forEach(function (event) {
            if (event.el_type !== 'note') return;
            if (event.startTriplet) triplet = Number(event.tripletMultiplier) || 1;
            var length = Number(event.duration) * triplet;
            if (Number.isFinite(length) && length > 0) {
