    inventory.some(function (part) {
      var events = harmonyForVoice(part);
      if (!events.length) return false;
      chordEvents = events;
      return true;
    });
    chordEvents.sort(function (a, b) { return a.start - b.start || (a.sourceStart || 0) - (b.sourceStart || 0); });
