 'no-bruremarsj-mixed': {label:'Norge · Bruremarsj 4/4 + 2/4 · kontrabas, lut, blid cajón',bass:'nordic',chords:'nordic',drums:'nordic',bassInstrument:32,chordInstrument:24}
};
function parseMeter(text) {
