}

/* Notated voices live inside the existing folded mixer, not in another toolbar. */
.huwabc-mixer-voices{grid-column:1 / -1;min-width:0;}
.huwabc-mixer-voices .huwabc-voice-controls{margin:3px 0 0;}

/* One visible track per notated voice. The exported Site player keeps its old folding behavior. */
.huwabc-voice-controls--inline{border:0;margin:0;padding:0;}
