.huwabc-voice-controls--inline .huwabc-voice-role{display:block;min-height:0;margin:0;font-size:10px;line-height:1.2;}
.huwabc-voice-controls--inline .huwabc-voice-fields{display:grid;grid-template-columns:minmax(115px,1.6fr) minmax(95px,1fr) auto;gap:8px;align-items:end;min-width:0;}
