.huwabc-voice-controls--inline .huwabc-voice-label{font-size:10px;margin:0 0 2px;}
.huwabc-voice-controls--inline select{min-height:28px;font-size:12px;}
.huwabc-voice-controls--inline .huwabc-voice-volume-controls{min-height:28px;gap:3px;}
.huwabc-voice-controls--inline .huwabc-voice-audible{min-height:28px;font-size:11px;gap:3px;}
.huwabc-voice-controls--inline .huwabc-voice-hint{font-size:11px;margin:6px 0;}
.huwabc-voice-controls--inline .huwabc-voice-bass-field{padding-top:7px;margin-top:7px;border-top:1px solid #e1e9e5;}
.huwabc-voice-controls--inline .huwabc-voice-bass-field>select{max-width:100%;min-height:28px;}
