.huwabc-voice-controls--inline .huwabc-voice-fields{grid-template-columns:minmax(110px,1.5fr) minmax(90px,1fr) 97px;align-items:end;}
.huwabc-voice-controls--inline .huwabc-voice-modes{height:28px;}
.huwabc-voice-controls--inline .huwabc-voice-mode{min-width:31px;font-size:11px;}
@container (max-width:380px){.huwabc-voice-controls--inline .huwabc-voice-modes{justify-self:end;}}

/* Version 0.3.36 – one three-state cycling switch per track. */
.huwabc-voice-modes{height:29px;border-radius:6px;}
