    var simple=s.endings.length===2&&s.endings[0].numbers.join(',')==='1'&&s.endings[1].numbers.join(',')==='2';
    var ending=simple?s.endings[pass===s.count?1:0]:s.endings.find(function(e){return e.numbers.indexOf(pass)>=0;});
