(function () {
  'use strict';
  var Planner = require('$:/plugins/huwiki/abc/repeat-plan.js');
  var EPSILON = 0.00002;
  var TIMING_FIELDS = ['currentTrackWholeNotes', 'currentTrackMilliseconds', 'midiPitches', 'midiGraceNotePitches'];

  var RENDER_FIELDS = { abselem: true, abcelem: true, graphelem: true, elemset: true, parent: true, staffGroup: true, engraver: true };
  function clonePlain(value, ancestors) {
    if (typeof value === 'function') return undefined;
    if (!value || typeof value !== 'object') return value;
    // Engraving attaches bidirectional AbsoluteElement/SVG references to AST
    // headers and notes, and also to metaText.tempo. Audio copies only music.
    if (typeof value.nodeType === 'number') return undefined;
    ancestors = ancestors || new Set();
    if (ancestors.has(value)) return undefined;
    ancestors.add(value);
    var result;
    if (Array.isArray(value)) result = value.map(function (item) { return clonePlain(item, ancestors); });
    else {
      result = {};
      Object.keys(value).forEach(function (key) {
        if (Object.prototype.hasOwnProperty.call(RENDER_FIELDS, key)) return;
        var copied = clonePlain(value[key], ancestors);
        if (copied !== undefined) result[key] = copied;
      });
    }
    ancestors.delete(value);
    return result;
  }

  function eventCopy(event) {
    // Keep the displayed event and its render graph intact. The linear audio
    // occurrence owns a separate copy of its musical data and timing fields.
    var copy = clonePlain(event);
    TIMING_FIELDS.forEach(function (key) { delete copy[key]; });
    if (event.el_type === 'bar') {
      copy.type = 'bar_thin';
      delete copy.startEnding;
      delete copy.endEnding;
    }
    return copy;
  }

  function numbers(value) {
    return (Array.isArray(value) ? value : [value]).filter(function (n) { return typeof n === 'number' && Number.isFinite(n); });
  }

  function label(index) { return 'Stemme ' + (index + 1); }

  function validate(model, plan) {
    if (!model || !model.voices || !model.voices.length || !plan.written || !plan.written.length) {
      throw new Error('Gentagelser: nodearket indeholder ingen læsbare takter.');
    }
    if (!Array.isArray(plan.order) || !plan.order.length || plan.order.some(function (index) {
      return !Number.isInteger(index) || index < 0 || index >= plan.written.length;
    })) throw new Error('Gentagelser: afspilningsrækkefølgen er ugyldig.');
    model.voices.forEach(function (voice, index) {
      if (voice.measures.length !== plan.written.length) {
        throw new Error('Gentagelser: ' + label(index) + ' har ' + voice.measures.length + ' noterede takter; den fælles plan har ' + plan.written.length + '. Kontrollér stemmernes taktstreger og pauser.');
      }
      voice.measures.forEach(function (measure, bar) {
        if (!Number.isFinite(measure.duration) || !(measure.duration > 0) || Math.abs(measure.duration - plan.written[bar].duration) > EPSILON) {
          throw new Error('Gentagelser: ' + label(index) + ', takt ' + (bar + 1) + ', har en anden længde end den fælles takt. Kontrollér noder og pauser.');
        }
      });
    });
  }

  function globalProgram(tune, options, header) {
    var midi = tune.formatting && tune.formatting.midi || {}, value = Number(options.program || 0), channel = Number(options.channel || 0), explicit = false;
    if (tune.formatting && tune.formatting.bagpipes) value = 71;
    if (midi.program && midi.program.length) {
      value = Number(midi.program[midi.program.length > 1 ? 1 : 0]);
      if (midi.program.length > 1) channel = Number(midi.program[0]);
      explicit = true;
    }
    if (midi.channel && midi.channel.length) { channel = Number(midi.channel[0]); explicit = true; }
    if (channel === 10 || header && header.clef && header.clef.type === 'perc' && !explicit) value = 128;
    return Number.isFinite(value) ? value : 0;
  }

  function initialTranspose(tune, options, header) {
    var midi = tune.formatting && tune.formatting.midi || {}, value = Number(options.midiTranspose || 0);
    if (tune.visualTranspose) value -= Number(tune.visualTranspose);
    if (midi.transpose && midi.transpose.length) value = Number(midi.transpose[0]);
    if (header && header.clef && header.clef.type === 'perc') value = 0;
    return Number.isFinite(value) ? value : 0;
  }

  function clefTranspose(clef, previous) {
    clef = clef || {};
    if (String(clef.type || '').indexOf('-8') >= 0) return -12;
    if (String(clef.type || '').indexOf('+8') >= 0) return 12;
    return Number.isFinite(Number(clef.transpose)) && Number(clef.transpose) !== 0 ? Number(clef.transpose) : previous;
  }

  var DYNAMICS = {
    pppp: [15, 10, 5, 1], ppp: [30, 20, 10, 1], pp: [45, 35, 20, 1], p: [60, 50, 35, 1],
    mp: [75, 65, 50, 1], mf: [90, 80, 65, 1], f: [105, 95, 80, 1], ff: [120, 110, 95, 1],
    fff: [127, 125, 110, 1], ffff: [127, 125, 110, 1]
