  function states(tune, voice, options) {
    var firstHeader = voice.measures[0].header || voice.header || {};
    var midi = tune.formatting && tune.formatting.midi || {};
    var current = {
      program: globalProgram(tune, options, firstHeader),
      transpose: clefTranspose(firstHeader.clef, initialTranspose(tune, options, firstHeader)),
      beat: midi.beat ? midi.beat.slice() : [105, 95, 85, 1],
      accent: !midi.nobeataccents,
