        previousClef = signature;
      }
      snapshots.push(clonePlain(current));
      measure.events.forEach(function (event) {
        (event.decoration || []).forEach(function (dynamic) {
          if (DYNAMICS[dynamic]) current.beat = DYNAMICS[dynamic].slice();
        });
        if (event.el_type === 'clef') current.transpose = clefTranspose(event, current.transpose);
        if (event.el_type !== 'midi') return;
        var params = event.params || [];
        if (event.cmd === 'program' && params.length) current.program = Number(params[0]);
        else if (event.cmd === 'channel' && Number(params[0]) === 10) current.program = 128;
        else if (event.cmd === 'transpose' && params.length) current.transpose = Number(params[0]);
        else if (event.cmd === 'beat') current.beat = params.slice();
        else if (event.cmd === 'beataccents') current.accent = true;
        else if (event.cmd === 'nobeataccents') current.accent = false;
        else if (['vol', 'swing', 'gchord', 'gchordoff', 'gchordon', 'bassvol', 'chordvol', 'bassprog', 'chordprog'].indexOf(event.cmd) >= 0) {
