  }

  function midiEvent(command, params) { return { el_type: 'midi', cmd: command, params: params, startChar: -1, endChar: -1 }; }

  function headerEvents(header, state, jump) {
    var events = [];
    ['key', 'meter', 'clef'].forEach(function (key) {
      if (header && header[key]) events.push(Object.assign(clonePlain(header[key]), { el_type: key, startChar: -1, endChar: -1 }));
