    events.push(midiEvent('program', [state.program]), midiEvent('transpose', [state.transpose]));
    if (jump) {
      events.push(midiEvent('beat', state.beat.slice()), midiEvent(state.accent ? 'beataccents' : 'nobeataccents', []));
