      state.plan.order.forEach(function (writtenIndex, playedIndex) {
        var measure = voice.measures[writtenIndex], jump = playedIndex > 0 && writtenIndex !== state.plan.order[playedIndex - 1] + 1;
        Array.prototype.push.apply(events, headerEvents(measure.header, snapshots[writtenIndex], jump));
        measure.events.forEach(function (original) {
