    linear.metaText = clonePlain(tune.metaText || {});
    return { tune: linear, noteCopies: noteCopies };
  }

  function transferTimings(model, copies) {
    var byOriginal = new Map();
    model.voices.forEach(function (voice) {
      voice.measures.forEach(function (measure) {
        measure.events.forEach(function (event) {
          if (event.el_type === 'note') byOriginal.set(event, { whole: [], ms: [], pitches: [], grace: [] });
