    copies.forEach(function (pair) {
      var target = byOriginal.get(pair.original), copy = pair.copy;
      Array.prototype.push.apply(target.whole, numbers(copy.currentTrackWholeNotes));
      Array.prototype.push.apply(target.ms, numbers(copy.currentTrackMilliseconds));
      // ABCJS keeps the most recent occurrence's MIDI data on its source node.
      // Preserve that convention while collecting every occurrence's clock.
      if (copy.midiPitches) target.pitches = copy.midiPitches.map(function (event) { return Object.assign({}, event); });
      if (copy.midiGraceNotePitches) target.grace = copy.midiGraceNotePitches.map(function (event) { return Object.assign({}, event); });
    });
    byOriginal.forEach(function (value, original) {
      TIMING_FIELDS.forEach(function (key) { delete original[key]; });
      if (value.whole.length) original.currentTrackWholeNotes = value.whole.length === 1 ? value.whole[0] : value.whole;
      if (value.ms.length) original.currentTrackMilliseconds = value.ms.length === 1 ? value.ms[0] : value.ms;
      if (value.pitches.length) original.midiPitches = value.pitches;
      if (value.grace.length) original.midiGraceNotePitches = value.grace;
    });
  }

  function sourceKey(event) {
    return event && Number.isFinite(event.startChar) && event.startChar >= 0 ?
      event.el_type + ':' + event.startChar + ':' + event.endChar : null;
  }

  function renderedMeasures(entries, voice, voiceIndex) {
    var byIdentity = new Map(), bySource = Object.create(null), groups = voice.measures.map(function () { return []; });
    voice.measures.forEach(function (measure, index) {
      measure.events.forEach(function (event) {
