      if (!event) return;
      var index = byIdentity.get(event), key = sourceKey(event);
      if (index === undefined && key && bySource[key] !== undefined) index = bySource[key];
      var length = Number(absolute.durationClass || absolute.duration || 0);
      if (index === undefined) {
        if (length > 0 && !(event.rest && event.rest.type === 'spacer')) throw new Error('Gentagelser: en vist node i ' + label(voiceIndex) + ' kunne ikke knyttes til en noteret takt.');
        return;
      }
      groups[index].push(entry);
    });
    groups.forEach(function (group, index) {
      if (!group.some(function (entry) { return Number(entry.elem.durationClass || entry.elem.duration || 0) > 0; })) {
        throw new Error('Gentagelser: den viste ' + label(voiceIndex) + ', takt ' + (index + 1) + ', mangler tidsbestemte noder.');
      }
    });
    return groups;
  }

  function playbackVoices(tune, state, nativeVoices) {
    if (nativeVoices.length !== state.model.voices.length) throw new Error('Gentagelser: de viste stemmer passer ikke til afspilningsplanen.');
    var tempoLocations = {}, hasTempo = false;
    var result = nativeVoices.map(function (entries, voiceIndex) {
      var groups = renderedMeasures(entries, state.model.voices[voiceIndex], voiceIndex), tempos = [], currentTempo = tune.getBpm(tune.metaText && tune.metaText.tempo);
