type: application/javascript
module-type: library
\*/
(function () {
'use strict';
var Planner = require('$:/plugins/huwiki/abc/repeat-plan.js');
var EPS = 0.00002;
var ACC = { natural: '=', sharp: '^', flat: '_', dblsharp: '^^', dblflat: '__', quartersharp: '^/', quarterflat: '_/' };
var ACC_VALUE = { natural: 0, sharp: 1, flat: -1, dblsharp: 2, dblflat: -2, quartersharp: 0.5, quarterflat: -0.5 };
var DYNAMIC = /^(?:p{1,4}|f{1,4}|mp|mf)$/;
var JUMP = /^(?:(?:D\.?\s*[CS]\.?(?:\s+al\s+(?:fine|coda))?)|fine|segno|coda|dacapo|dasegno|tocoda)$/i;
function fail(text) { throw new Error('Taktudsnit: ' + text); }
function integer(value, label) {
 var n = Number(value);
 if (!Number.isInteger(n) || n < 1) fail(label + ' skal være et positivt heltal.');
 return n;
}
function quote(text) { return '"' + String(text || '').replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/[\r\n]/g, ' ') + '"'; }
function fraction(value) {
 if (!(value > 0) || !Number.isFinite(value)) fail('en nodeværdi kan ikke læses.');
 for (var d = 1; d <= 4096; d++) {
  var n = Math.round(value * d);
  if (n > 0 && Math.abs(n / d - value) < 1e-9) return n + '/' + d;
 }
 fail('en nodeværdi kan ikke afgrænses sikkert.');
}
function meterText(meter) {
 if (!meter || meter.type === 'none') return 'none';
 if (meter.type === 'common_time') return 'C';
 if (meter.type === 'cut_time') return 'C|';
 if (meter.type !== 'specified' || !meter.value || !meter.value.length) fail('taktarten kan ikke læses.');
 return meter.value.map(function (part) { return String(part.num) + '/' + String(part.den); }).join('+');
}
function clefText(clef) {
 clef = clef || {};
 var type = String(clef.type || 'treble');
 if (!/^[a-z]+(?:[1-5])?(?:[+-]8)?$/.test(type)) fail('nøglen kan ikke bevares sikkert.');
 var text = 'clef=' + type;
 if (Number.isFinite(clef.transpose) && clef.transpose !== 0) text += ' transpose=' + clef.transpose;
 return text;
}
function keyMap(key) {
 var out = {}; (key && key.accidentals || []).forEach(function (acc) {
  if (ACC_VALUE[acc.acc] === undefined) fail('toneartens fortegn understøttes ikke i et udsnit.');
  out[String(acc.note).slice(0, 1).toUpperCase()] = ACC_VALUE[acc.acc];
 }); return out;
}
function accString(value) {
 var name = Object.keys(ACC_VALUE).find(function (key) { return ACC_VALUE[key] === value; });
 if (!name) fail('et fortegn understøttes ikke i et udsnit.');
 return ACC[name];
}
function keyWriter(ABC) {
 var cache = {};
 return function (key) {
  key = key || { root: 'C', accidentals: [] };
  var base = String(key.root || 'C') + String(key.acc || '') + String(key.mode || '');
  if (!/^(?:[A-G](?:#|b)?(?:[A-Za-z]+)?|none|HP|Hp)$/.test(base)) fail('tonearten kan ikke bevares sikkert.');
  if (!cache[base]) {
   var parsed = ABC.parseOnly('X:1\nL:1/4\nK:' + base + '\nC4|')[0];
   var staff = parsed && parsed.lines.find(function (line) { return line.staff; });
   cache[base] = keyMap(staff && staff.staff[0].key);
  }
  var standard = cache[base], target = keyMap(key), text = base;
  'CDEFGAB'.split('').forEach(function (letter) {
   var expected = standard[letter] || 0, actual = target[letter] || 0;
   if (actual !== expected) text += ' ' + accString(actual) + letter;
  });
  return text;
 };
}
function tempoText(tempo) {
 if (!tempo || !(tempo.bpm > 0)) return '';
 return (tempo.duration && tempo.duration.length ? tempo.duration : [0.25]).map(fraction).join(' ') + '=' + tempo.bpm;
}
function midiText(event) {
 var command = String(event.cmd || '');
 if (!/^[a-z][a-z0-9]*$/i.test(command)) fail('en MIDI-indstilling kan ikke læses.');
 var params = (event.params || []).map(function (value) {
  var text = String(value); if (/[\]\r\n]/.test(text)) fail('en MIDI-indstilling kan ikke afgrænses sikkert.'); return text;
 });
 return '[I:MIDI=' + command + (params.length ? ' ' + params.join(' ') : '') + ']';
}

// ABCJS omits L: fields from its AST. Read them outside quoted annotations,
// comments and other fields; changing L: is global in the shipped ABC parser.
function lengthChanges(source, initialMeter) {
 var changes = [], total = 1;
 if (initialMeter && initialMeter.type === 'specified') total = (initialMeter.value || []).reduce(function (sum, part) { return sum + String(part.num).split('+').reduce(function (s, n) { return s + Number(n.replace(/[()]/g, '')); }, 0) / Number(part.den); }, 0);
 var initial = total < 0.75 ? 1 / 16 : 1 / 8;
 function add(text, at) {
  var m = /^\s*(\d+)\s*\/\s*(\d+)/.exec(text);
  if (!m || !(Number(m[1]) > 0) || !(Number(m[2]) > 0)) fail('L:-nodeværdien er ugyldig.');
  changes.push({ at: at, value: Number(m[1]) / Number(m[2]) });
 }
 var offset = 0, block = false;
 source.split('\n').forEach(function (line) {
  var begin = /^\s*%%begin/i.test(line), end = /^\s*%%end/i.test(line);
  if (begin) block = true;
  if (!block) {
   var field = /^\s*([A-Za-z]):(.*)$/.exec(line);
   if (field) { if (field[1] === 'L') add(field[2], offset); }
   else if (!/^\s*%/.test(line)) {
    for (var i = 0; i < line.length;) {
     var c = line.charAt(i);
     if (c === '%') break;
     if (c === '"' || c === '!' || c === '+') {
      var delimiter = c; i++;
      while (i < line.length) { if (line.charAt(i) === '\\') i += 2; else if (line.charAt(i++) === delimiter) break; }
     } else if (c === '[' && /^[A-Za-z]:/.test(line.slice(i + 1, i + 3))) {
      var closing = line.indexOf(']', i + 3); if (closing < 0) break;
      if (line.charAt(i + 1) === 'L') add(line.slice(i + 3, closing), offset + i);
      i = closing + 1;
     } else i++;
    }
   }
  }
  if (end) block = false;
  offset += line.length + 1;
 });
 return function (position) {
  var result = initial; for (var i = 0; i < changes.length && changes[i].at <= position; i++) result = changes[i].value; return result;
 };
}
function musicTokens(raw) {
 var tokens = [], grace = 0;
 for (var i = 0; i < raw.length;) {
  var c = raw.charAt(i);
  if (c === '"' || c === '!' || c === '+') {
   var begin = i++, delimiter = c;
   while (i < raw.length) { if (raw.charAt(i) === '\\') i += 2; else if (raw.charAt(i++) === delimiter) break; }
   tokens.push({ type: delimiter === '"' ? 'text' : 'decoration', start: begin, end: i, text: raw.slice(begin + 1, i - 1) });
  } else if (c === '{') { grace++; i++; }
  else if (c === '}') { grace--; i++; }
  else if (!grace && (c === '(' && !/\d/.test(raw.charAt(i + 1)) || c === ')')) { tokens.push({ type: c, start: i > 0 && raw.charAt(i - 1) === '.' ? i - 1 : i, end: i + 1 }); i++; }
  else if (!grace && c === '-') { tokens.push({ type: 'tie', start: i > 0 && raw.charAt(i - 1) === '.' ? i - 1 : i, end: i + 1 }); i++; }
  else if (!grace && c === ']') { tokens.push({ type: 'chordEnd', start: i, end: i + 1 }); i++; }
  else if (!grace && /^[\^_=A-Ga-g]/.test(c)) {
   var match = /^(?:\^{1,2}|_{1,2}|=)?(?:\/)?[A-Ga-g][,']*/.exec(raw.slice(i));
   if (match) { tokens.push({ type: 'pitch', start: i, end: i + match[0].length, text: match[0] }); i += match[0].length; }
   else i++;
  } else i++;
 }
 return tokens;
}
function patch(raw, edits) {
 edits.sort(function (a, b) { return b.start - a.start; });
 edits.forEach(function (edit) { raw = raw.slice(0, edit.start) + (edit.replacement || '') + raw.slice(edit.end); }); return raw;
}
function noteRaws(source, voice, start, end) {
 var selected = [], pending = {}, keptTies = new Set(), incoming = new Set(), effective = new Map(), tied = {};
 voice.measures.forEach(function (measure, bar) {
  var key = keyMap(measure.header.key), accidentals = {};
  measure.events.forEach(function (event) {
   if (event.el_type === 'key') { key = keyMap(event); accidentals = {}; }
   if (event.el_type !== 'note') return;
   (event.pitches || []).forEach(function (pitch) {
    var letter = 'CDEFGAB'.charAt((pitch.pitch % 7 + 7) % 7), value;
    if (pitch.accidental) {
     value = ACC_VALUE[pitch.accidental]; if (value === undefined) fail('et fortegn kan ikke bevares sikkert.'); accidentals[pitch.pitch] = value;
    } else if (pitch.endTie && tied[pitch.pitch] !== undefined) value = tied[pitch.pitch];
    else value = accidentals[pitch.pitch] === undefined ? key[letter] || 0 : accidentals[pitch.pitch];
    effective.set(pitch, value);
    if (pitch.startTie) tied[pitch.pitch] = value; else if (pitch.endTie) delete tied[pitch.pitch];
   });
   if (bar >= start && bar < end) selected.push(event);
  });
 });
 selected.forEach(function (event) {
  (event.pitches || []).forEach(function (pitch) {
   if (pitch.endTie) { if (pending[pitch.pitch]) keptTies.add(pending[pitch.pitch]); else incoming.add(pitch); delete pending[pitch.pitch]; }
   if (pitch.startTie) pending[pitch.pitch] = pitch;
  });
 });
 var raws = new Map(), openSlurs = [], entries = [];
 selected.forEach(function (event) {
  if (!Number.isInteger(event.startChar) || !Number.isInteger(event.endChar) || event.startChar < 0 || event.endChar <= event.startChar) fail('en node mangler en sikker position i ABC-kilden.');
  var raw = source.slice(event.startChar, event.endChar), edits = [], tokens = musicTokens(raw), pitchIndex = -1, chordEnd = false;
  var pitches = event.pitches || [], pitchTokens = tokens.filter(function (token) { return token.type === 'pitch'; });
  if (pitchTokens.length !== pitches.length) fail('en nodefigur kan ikke afgrænses sikkert.');
  tokens.forEach(function (token) {
   if (token.type === 'pitch') {
    pitchIndex++; chordEnd = false;
    if (incoming.has(pitches[pitchIndex])) edits.push({ start: token.start, end: token.end, replacement: accString(effective.get(pitches[pitchIndex])) + token.text.replace(/^[\^_=\/]+/, '') });
   } else if (token.type === 'chordEnd') chordEnd = true;
   else if (token.type === 'tie') {
    if (chordEnd) {
     var tiedPitches = pitches.filter(function (pitch) { return pitch.startTie; }), kept = tiedPitches.filter(function (pitch) { return keptTies.has(pitch); });
     if (kept.length && kept.length !== tiedPitches.length) fail('et akkordbindebånd går delvist uden for udsnittet; vælg en ekstra takt.');
     if (!kept.length) edits.push(token);
    } else if (!pitches[pitchIndex] || !keptTies.has(pitches[pitchIndex])) edits.push(token);
   } else if (token.type === '(') openSlurs.push({ edits: edits, token: token });
   else if (token.type === ')') { if (openSlurs.length) openSlurs.pop(); else edits.push(token); }
   else if (token.type === 'text') {
    var placed = /^[\^_<>]/.test(token.text), content = placed ? token.text.slice(1).trim() : '';
    if (placed && (Planner.countText(content) || JUMP.test(content))) edits.push(token);
   } else if (token.type === 'decoration' && JUMP.test(token.text)) edits.push(token);
  });
  entries.push({ event: event, raw: raw, edits: edits });
 });
 openSlurs.forEach(function (open) { open.edits.push(open.token); });
 entries.forEach(function (entry) { raws.set(entry.event, patch(entry.raw, entry.edits)); });
 return raws;
}
function timelineEvents(model, tune) {
 var events = [], defaultTempo = tune.metaText && tune.metaText.tempo;
 if (defaultTempo) events.push({ time: -1, event: defaultTempo });
 model.voices.forEach(function (voice) {
  var triplet = 1;
  voice.measures.forEach(function (measure) {
   var offset = 0;
   measure.events.forEach(function (event) {
    if (event.el_type === 'tempo') events.push({ time: measure.start + offset, event: event });
    if (event.startTriplet) triplet = event.tripletMultiplier || 1;
    if (event.el_type === 'note') offset += event.duration * triplet;
    if (event.endTriplet) triplet = 1;
   });
  });
 });
 events.sort(function (a, b) { return a.time - b.time; }); return events;
}
function beforeState(voice, start) {
 var state = { midi: {}, dynamic: '', chord: '', stem: '' }, tuple = false;
 voice.measures.forEach(function (measure, index) {
  if (index >= start) return;
  measure.events.forEach(function (event) {
   if (event.el_type === 'midi') state.midi[event.cmd === 'gchordon' || event.cmd === 'gchordoff' ? 'gchordOn' : event.cmd] = event;
   if (event.el_type === 'stem' && /^(up|down|auto)$/.test(event.direction)) state.stem = event.direction;
   (event.decoration || []).forEach(function (text) { if (DYNAMIC.test(text)) state.dynamic = text; });
   (event.chord || []).forEach(function (chord) { if (chord.position === 'default') state.chord = chord.name; });
   if (event.startTriplet) tuple = true; if (event.endTriplet) tuple = false;
  });
 });
 if (tuple) fail('udsnittet begynder midt i en triol eller anden tuplet; medtag den foregående takt.');
 state.tuple = tuple; return state;
}
function lyrics(events) {
 var notes = events.filter(function (event) { return event.el_type === 'note' && event.pitches && event.pitches.length; });
