.huwabc-score.huwabc-minimal .huwabc-page-shell{margin-top:0}
.huw-music-media-abc:has(>.huwabc-score.huwabc-standalone.huwabc-minimal)>.huw-music-section-label{display:none!important}


/* Complete ABC chord charts: retain all measures, repeats and parts in one view.
   Rendered ABCJS SVGs remain in the DOM for audio timings, but are not painted. */
.huwabc-chord-overview-player{max-width:100%;min-width:0;box-sizing:border-box;border:1px solid #cbdcd3;border-radius:12px;padding:9px;background:#fffdf8}
.huwabc-chord-overview-player .huwabc-minimal-paper{width:100%;max-height:none!important;min-height:0!important;height:auto!important;overflow:visible!important;position:relative;padding:0;margin:0}
/* Rendered ABCJS staff SVGs may be wrapped in DIVs. Every generated
   score wrapper must be out of flow; otherwise it leaves a blank A4-sized
   space above the real chord chart. Keep nodes mounted for audio timing. */
.huwabc-chord-overview-player .huwabc-minimal-paper>.huwabc-chord-overview-source{
 position:absolute!important;inset:0 auto auto 0!important;
 display:block!important;width:1px!important;height:1px!important;
 min-width:0!important;min-height:0!important;max-width:1px!important;max-height:1px!important;
 padding:0!important;margin:0!important;border:0!important;
 overflow:hidden!important;opacity:0!important;pointer-events:none!important
}
.huwabc-chord-overview-player .huwabc-minimal-paper>.huwabc-chord-overview{position:relative;z-index:1;}
.huwabc-chord-overview{display:grid;gap:17px;width:100%;box-sizing:border-box;padding:12px 7px}
.huwabc-chord-overview-row{display:grid;grid-template-columns:minmax(35px,66px) minmax(0,1fr);align-items:center;gap:9px;min-width:0}
.huwabc-chord-overview-part{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;min-width:0;line-height:1.25}
