button.huwabc-preparing{display:inline-flex!important;align-items:center;justify-content:center;gap:6px;min-width:94px!important;width:auto!important;cursor:progress;animation:none!important;}
button.huwabc-preparing>:not(.huwabc-preparing-spinner):not(.huwabc-preparing-label){display:none!important;}
button.huwabc-preparing>.huwabc-preparing-spinner{display:inline-block!important;width:12px;height:12px;flex:0 0 12px;box-sizing:border-box;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:huwabc-preparing-spin .8s linear infinite;}
