.huwabc-page-shell{display:block;min-width:0;color:#214a40;background:#f5f8f6;border:1px solid #dbe5df;border-radius:10px;margin:10px 12px;overflow:visible;box-sizing:border-box;container-type:inline-size;container-name:huwpages}
.huwabc-page-toolbar{display:flex;flex-wrap:wrap;gap:8px;align-items:end;padding:9px 10px;border-bottom:1px solid #dee7e1;background:#f6faf7;border-radius:10px 10px 0 0}
