.huwabc-page-button{box-sizing:border-box;border:1px solid #bcd3c6;background:#fff;color:#235c49;border-radius:7px;padding:6px 10px;font:600 12px/1.3 system-ui;min-height:32px;cursor:pointer;white-space:nowrap;margin:0}
.huwabc-page-button:hover{background:#e4f1e9}.huwabc-page-button:focus-visible,.huwabc-page-select:focus-visible{outline:2px solid #258066;outline-offset:2px}
.huwabc-page-button[aria-pressed=true]{background:#276f5b;color:white;border-color:#276f5b}.huwabc-page-button:disabled{opacity:.4;cursor:default}
.huwabc-page-desk{margin-left:auto}.huwabc-page-follow{min-width:134px}
.huwabc-page-viewport{width:100%;position:relative;overflow:auto;overscroll-behavior:contain;scroll-behavior:auto;box-sizing:border-box;scrollbar-gutter:stable;touch-action:pan-y pinch-zoom;overflow-anchor:none}
.huwabc-page-shell .huwabc-paginated{width:100%!important;display:block!important;padding:0!important;margin:0!important;min-height:0!important;border:0!important;border-radius:0!important;background:transparent!important;overflow:visible!important;position:relative!important;box-sizing:border-box;vertical-align:initial!important}
.huwabc-pages-track{display:flex;align-items:flex-start;justify-content:center;gap:12px;width:var(--huwabc-track-width,100%);box-sizing:border-box;padding:4px 0}
