.huwabc-page-shell [hidden]{display:none!important}
.huwabc-page-nav{display:grid;grid-template-columns:34px minmax(0,1fr) auto 34px;align-items:center;gap:5px;min-height:44px;padding:5px 9px;box-sizing:border-box;border-top:1px solid #dee7e1}
