.huwabc-page-dots{grid-column:2;display:flex;justify-content:center;align-items:center;gap:0;min-width:0}.huwabc-page-jump{grid-column:2;width:100%;max-width:180px;justify-self:center}
.huwabc-page-dot{display:inline-flex;align-items:center;justify-content:center;width:32px;height:34px;min-width:18px;padding:0;border:0;background:transparent!important;border-radius:6px;flex:0 1 32px}
