.huwabc-page-transport:empty{display:none}.huwabc-page-transport{padding:8px 12px;background:#f4faf6;border-top:1px solid #d1dfd6;flex:none}
.huwabc-page-is-desk .abcjs-chord{cursor:default!important}.huwabc-page-is-desk .huwabc-page-folio{font-size:11px}
@container huwpages (max-width:440px){.huwabc-page-toolbar{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:6px;padding:7px}.huwabc-page-choice{min-width:0}.huwabc-page-select{width:100%;min-width:0;box-sizing:border-box}.huwabc-page-follow,.huwabc-page-desk{min-width:0;margin:0;width:100%;padding:6px;min-height:36px;font-size:11px}.huwabc-page-counter{min-width:65px;font-size:10px}.huwabc-page-nav{padding:4px;gap:1px}.huwabc-page-dot{height:36px}.huwabc-page-ahead-label{width:80px;font-size:10px}}
