   var counts={};labels.forEach(function(n){var c=(n.getAttribute('class')||'').match(/\babcjs-v(\d+)\b/);if(c)counts[c[1]]=(counts[c[1]]||0)+1;});
   var best=Object.keys(counts).sort(function(a,b){return counts[b]-counts[a];});
   if(best.length)preferred=Number(best[0])+1;
  }
