   Array.prototype.forEach.call(candidates,function(el){var r=safeBBox(el);if(!r||r.width<=0&&r.height<=0)return;top=Math.min(top,r.y);bottom=Math.max(bottom,r.y+r.height);});
   if(!Number.isFinite(top)||!Number.isFinite(bottom)){svg.style.display='none';return;}
