   Array.prototype.forEach.call(svg.querySelectorAll('.abcjs-staff-wrapper > *'),function(child){
    var c=(child.getAttribute('class')||'').match(/\babcjs-v(\d+)\b/);
    if(c&&Number(c[1])!==index)child.style.visibility='hidden';
   });
   var units=Math.min(width,Math.max(70,(paper.clientWidth||440)/zoom));
   var info={fullWidth:width,units:units,x:0,y:y,height:h,scale:zoom,labels:labels,active:null};
   metrics.set(svg,info);
   svg.setAttribute('viewBox','0 '+y+' '+units+' '+h);
   svg.setAttribute('preserveAspectRatio','xMinYMin meet');
   svg.style.maxWidth='none';svg.style.width=(units*zoom)+'px';svg.style.height=(h*zoom)+'px';
   svg.setAttribute('data-huwabc-follow-frame',String(frames.length));
   svg.style.display='none';frames.push(svg);
   heights.push(h*zoom);
  });
  if(frames.length){current=frames[0];current.style.display='block';paper.removeAttribute('data-huwabc-follow-empty');}
  else paper.setAttribute('data-huwabc-follow-empty','yes');
  // Reserve a FIXED height for every system in this player. The height no
  // longer follows the different SVG bbox of each line while the music plays.
  var reserve=heights.length?Math.max.apply(null,heights):0;
  reserve=Math.max(chordsOnly?66:130,Math.ceil(reserve)+4);
  paper.style.height=reserve+'px';paper.style.minHeight=reserve+'px';paper.style.maxHeight=reserve+'px';
  lastWidth=0;resize();
 }
 function activate(svg){if(!svg||frames.indexOf(svg)<0)return false;if(svg!==current){if(current)current.style.display='none';current=svg;current.style.display='block';}return true;}
 function note(event){
  if(closed||!event)return null;
  var groups=event.elements||[],matched=null;
  for(var i=0;i<groups.length&&!matched;i++){
   var items=Array.isArray(groups[i])?groups[i]:[groups[i]];
   for(var j=0;j<items.length;j++){
    var n=items[j];if(!isVoice(n)||!n.ownerSVGElement||frames.indexOf(n.ownerSVGElement)<0)continue;
    if(n.classList&&n.classList.contains('abcjs-note')){matched=n;break;}
    if(!matched)matched=n;
   }
  }
  return matched;
 }
 function highlightChord(svg,x){
  if(!showChords)return;
  var info=metrics.get(svg);if(!info)return;
  var selected=null;
  for(var i=0;i<info.labels.length;i++){
   if(Number(info.labels[i].getAttribute('data-huwabc-chord-x'))<=x+2)selected=info.labels[i];else break;
  }
  if(info.active&&info.active!==selected)info.active.classList.remove('huwabc-follow-chord-current');
  if(selected)selected.classList.add('huwabc-follow-chord-current');
  info.active=selected;
 }
 function follow(event){
  var n=note(event);if(!n)return null;
  var svg=n.ownerSVGElement;if(!activate(svg))return null;
  var info=metrics.get(svg);
  if(info&&typeof n.getBBox==='function'){
   var bb=n.getBBox(),noteX=bb.x+bb.width/2,win=info.units;
   highlightChord(svg,noteX);
   if(noteX<info.x+win*.18||noteX>info.x+win*.74){
    var next=Math.max(0,Math.min(info.fullWidth-win,noteX-win*.42));
    if(Math.abs(next-info.x)>1){
     info.x=next;
     svg.setAttribute('viewBox',next+' '+info.y+' '+win+' '+info.height);
    }
   }
