 }
 function reset(){
  if(!frames.length)return;
  activate(frames[0]);frames.forEach(function(svg){var m=metrics.get(svg);if(m){m.x=0;if(m.active)m.active.classList.remove('huwabc-follow-chord-current');m.active=null;svg.setAttribute('viewBox','0 '+m.y+' '+m.units+' '+m.height);}});
 }
 function destroy(){closed=true;if(typeof window!=='undefined')window.removeEventListener('resize',resize);frames=[];current=null;}
