","type":"application/javascript","module-type":"library"},"$:/plugins/huwiki/abc/floating-mixer.css":{"title":"$:/plugins/huwiki/abc/floating-mixer.css","text":"/* Mini-mixer docks in the ordinary TW sidebar or can be detached and moved. */
.huwabc-mini-mixer{--mini-ink:#244b40;box-sizing:border-box;display:block;width:100%;max-width:100%;min-width:0;margin:9px 0 12px;padding:0 0 5px;background:#f7fbf8;border:1px solid #bed2c7;border-radius:8px;color:var(--mini-ink);font:12px/1.3 system-ui,-apple-system,sans-serif;box-shadow:0 1px 3px #163b2712;}
