.huwabc-mini-mixer-detach:hover{background:#d9ebe0;}
.huwabc-mini-mixer-list{padding:5px 6px;display:grid;gap:4px;}
.huwabc-mini-mixer-row{display:grid;grid-template-columns:minmax(52px,.6fr) minmax(63px,1fr) auto;align-items:center;gap:5px;border:1px solid #e0eae2;background:#fff;border-radius:5px;padding:4px 5px;min-width:0;min-height:38px;}
.huwabc-mini-mixer-name{display:flex;align-items:center;gap:3px;min-width:0;font-size:10px;overflow:hidden;white-space:nowrap;}
.huwabc-mini-mixer-name b{flex:none;font-size:11px;}
.huwabc-mini-mixer-instrument{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0;}
.huwabc-mini-mixer-level{display:flex;align-items:center;gap:3px;min-width:0;}
.huwabc-mini-mixer-slider{margin:0;min-width:30px;flex:1;width:100%;height:18px;accent-color:#277861;}
