var Sequence = require('$:/plugins/huwiki/abc/audio-sequence.js');
function aborted() { var e = new Error('Lydforberedelsen blev afbrudt.'); e.name = 'AbortError'; return e; }
function check(cancelled) { if (cancelled && cancelled()) throw aborted(); }
function makeContext(frames, rate) {
 var C = (typeof window !== 'undefined' && (window.OfflineAudioContext || window.webkitOfflineAudioContext));
 if (!C) throw new Error('Browseren understøtter ikke offline-rendering af TinySynth.');
 return new C(2, frames, rate);
}
function cleanup(synth) {
 if (!synth) return;
 // TinySynth's housekeeping timer must not survive the offline render.
 if (synth.huwikiTimer) clearInterval(synth.huwikiTimer);
 synth.playing = 0;
 synth.actx = null;
}
function assignedChannels(notes, rate) {
 // ABC tracks may change programs, but a TinySynth MIDI channel must have
 // exactly one program and fine tuning while notes overlap. The core sequence
 // allocator assigns those combinations deterministically.
 return Sequence.createEvents(notes, rate);
}
function setInstrument(synth, key, channel) {
 if (key === 'drums') { synth.rhythm[channel] = 1; return; }
 var colon = key.indexOf(':'), program = Number(key.slice(0,colon)), cents = Number(key.slice(colon+1));
 if (!Number.isInteger(program) || program < 0 || program > 127) throw new Error('TinySynth: ukendt instrumentnummer.');
 if (!Number.isFinite(cents) || Math.abs(cents) > 1200) throw new Error('TinySynth: ugyldig stemning.');
 synth.setProgram(channel, program);
 synth.tuningF[channel] = Math.round(cents / 100 * 8192);
}
async function render(notes, duration, audioContext, options) {
 options = options || {};
 var cancelled = options.cancelled, rate = audioContext.sampleRate;
 if (!Number.isFinite(rate) || rate < 8000 || rate > 192000) throw new Error('TinySynth: ugyldig samplerate.');
 var frames = Math.max(1, Math.ceil(duration * rate)), parts = Object.create(null), buffers = {};
 notes.forEach(function (n) { if (!parts[n.part]) parts[n.part] = []; parts[n.part].push(n); });
 var keys = Object.keys(parts);
 if (!keys.length) { buffers.melodyVolume = audioContext.createBuffer(2, frames, rate); return buffers; }
 for (var i=0; i<keys.length; i++) {
  check(cancelled);
  var part=keys[i], offline=makeContext(frames,rate), tiny=null;
  try {
   tiny=new TinySynth({internalcontext:0,useReverb:0,quality:1,voices:96});
   tiny.setAudioContext(offline,offline.destination);
   tiny.setMasterVol(.8);
   // OfflineAudioContext receives the ENTIRE timeline at once. The upstream
   // voice limit counts future scheduled notes against notes at t=0, then
   // prunes early notes before the PCM is rendered. That made voices enter
   // minutes late on multi-voice Jingle. Let the offline renderer schedule
   // all notes; channel gain is still controlled live by the outer mixer.
   // Disable housekeeping too: it assumes real-time WebAudio timing.
   if(tiny.huwikiTimer){clearInterval(tiny.huwikiTimer);tiny.huwikiTimer=null;}
   tiny._limitVoices=function(){};
   var allocated=assignedChannels(parts[part],rate);
   allocated.channels.forEach(function(channel,key){setInstrument(tiny,key,channel);});
   allocated.events.forEach(function(event) {
    var time = event.frame / rate, pitch=event.note.pitch;
    if (event.on) tiny.noteOn(event.channel,pitch,event.note.velocity,time);
    else tiny.noteOff(event.channel,pitch,time);
   });
   check(cancelled);
   var pcm=await offline.startRendering();
   check(cancelled);
   var maximum=0, silent=true;
   for(var c=0;c<pcm.numberOfChannels;c++) {
    var samples=pcm.getChannelData(c);
    for(var j=0;j<samples.length;j++) {
     if (!Number.isFinite(samples[j])) throw new Error('TinySynth gav ugyldige lyddata.');
     if ((j&16383)===0) { check(cancelled); }
     if (Math.abs(samples[j])>1e-6) {silent=false; maximum=Math.max(maximum,Math.abs(samples[j]));}
    }
   }
   if (silent) throw new Error('TinySynth gav tavs lyd i '+part+'.');
   buffers[part]=pcm;
   if (options.onProgress) options.onProgress({fraction:(i+1)/keys.length,part:part,peak:maximum});
  } finally { cleanup(tiny); }
 }
 return buffers;
}
exports.render=render;
exports.info=function(){return {engine:'tiny',runtime:'WebAudio TinySynth',soundfont:'Ingen – indbygget WebAudio',local:true,bundled:true};};
})();
