title: $:/plugins/huwiki/abc/chord-chart.js
type: application/javascript
module-type: library
\*/
(function(){
'use strict';
// Parse actual ABC chord annotations on note events. Every chord change remains
// visible in the compact chart, including multiple changes within one measure.
// Map any notated voice's source offsets to musical positions so the existing
// ABCJS timing callback can highlight the right chord, even across repeats.
function extract(ABC,source){
 var result={chords:[],noteTimes:{},measures:[]},tune;
 try{tune=ABC.parseOnly(String(source||''))[0];}catch(ignore){return result;}
 if(!tune||!Array.isArray(tune.lines))return result;
 var tracks={},order=0;
 tune.lines.forEach(function(line){
  (line.staff||[]).forEach(function(staff,si){
   (staff.voices||[]).forEach(function(events,vi){
    var key=si+':'+vi,track=tracks[key]||(tracks[key]={time:0,measure:1,hasNotes:false,tupletFactor:1,chords:[],id:key});
    (events||[]).forEach(function(ev){
     if(ev.el_type==='bar'){
      if(track.hasNotes){track.measure++;track.hasNotes=false;}
      return;
     }
     if(ev.el_type!=='note')return;
     // ABCJS stores the written duration of notes in tuplets. The actual
     // playback time uses tripletMultiplier until endTriplet. Without this,
     // voices drift apart and the highlighted chord jumps back and forth.
     if(ev.startTriplet)track.tupletFactor=Number(ev.tripletMultiplier)||1;
     var start=track.time;
     if(Number.isFinite(ev.startChar))result.noteTimes[String(ev.startChar)]=start;
     (ev.chord||[]).forEach(function(c){
      if(!c||!c.name||(c.position&&c.position!=='default'))return;
      track.chords.push({name:String(c.name),time:start,measure:track.measure,startChar:ev.startChar,order:order++});
     });
     track.time+=Math.max(0,Number(ev.duration)||0)*track.tupletFactor;
     if(ev.endTriplet)track.tupletFactor=1;
     track.hasNotes=true;
    });
   });
  });
 });
 var groups=Object.keys(tracks).map(function(key){return tracks[key];});
 // Prefer the chord-bearing voice as the measure authority (often bass voice),
 // but retain additional symbols from other staves rather than omitting them.
 groups.sort(function(a,b){return b.chords.length-a.chords.length;});
 var authoritative=groups[0],all=[];
 groups.forEach(function(track){track.chords.forEach(function(c){all.push(Object.assign({track:track.id},c));});});
 all.sort(function(a,b){return a.time-b.time||a.order-b.order;});
 var seen={};
 all.forEach(function(c){
  var key=c.time.toFixed(7)+'|'+c.name;
  if(seen[key])return;seen[key]=true;
  if(authoritative&&c.track!==authoritative.id){
   var near=authoritative.chords.filter(function(z){return z.time<=c.time+1e-7;}).pop();
   if(near)c.measure=near.measure;
  }
  c.index=result.chords.length;result.chords.push(c);
 });
 result.chords.forEach(function(c){
  if(!result.measures.length||result.measures[result.measures.length-1].number!==c.measure)
   result.measures.push({number:c.measure,chords:[]});
  result.measures[result.measures.length-1].chords.push(c);
 });
 return result;
}
function atEvent(chart,event){
 if(!chart||!chart.chords.length||!event)return -1;
 var time=chart.noteTimes[String(event.startChar)];
 if(!Number.isFinite(time))time=chart.noteTimes[String(event.endChar)];
 if(!Number.isFinite(time))return -1;
 var lo=0,hi=chart.chords.length-1,hit=-1;
 while(lo<=hi){var mid=(lo+hi)>>1;
  if(chart.chords[mid].time<=time+0.00001){hit=mid;lo=mid+1;}else hi=mid-1;
 }
 return hit;
}
exports.extract=extract;exports.atEvent=atEvent;
})();
