title: $:/plugins/huwiki/abc/reader-fallback.js
type: application/javascript
module-type: filteroperator
\*/
(function(){
"use strict";

// ViewAddon supplies the ordinary reader when a score's body contains prose.
// Some imported and AniMus scores already contain their own reader. Rendering
// both creates two real players and two sidebar mixers for the same score.
// Inspect parsed widgets, rather than matching examples/comments in raw text.
function attributeValue(attribute,current,wiki){
 if(!attribute)return current;
 if(attribute.type==='string')return attribute.value;
 if(attribute.type==='macro'){
  var value=attribute.value,variable=value&&value.attributes&&value.attributes.$variable;
  if(variable&&variable.type==='string'&&variable.value==='currentTiddler')return current;
  if(value&&value.name==='currentTiddler')return current;
 }
 if(attribute.type==='indirect'&&current&&/^!![^!]+$/.test(attribute.textReference||'')){
  var t=wiki.getTiddler(current);return t&&t.fields[attribute.textReference.slice(2)];
 }
 return undefined;
}
function containsReader(nodes,title,current,wiki){
 return (nodes||[]).some(function(node){
  var attributes=node.attributes||{},next=current;
  if(node.type==='huwiki-abc')return attributeValue(attributes.tiddler,current,wiki)===title;
  if(node.type==='tiddler')next=attributeValue(attributes.tiddler,current,wiki);
  else if(node.type==='set'){
   var name=attributeValue(attributes.name,undefined,wiki);
   if(name==='currentTiddler')next=attributeValue(attributes.value,current,wiki);
   else if(name===undefined)return false;
  }else if(node.type==='let'||node.type==='vars'){
   if(attributes.currentTiddler)next=attributeValue(attributes.currentTiddler,current,wiki);
  }else if(node.type!=='element'){
   // Lists, reveals and transclusions can change context or hide their body.
   // An uncertain, conditional reader must not suppress the reliable fallback.
   return false;
  }
  return containsReader(node.children,title,next,wiki);
 });
}
exports['huwiki-abc-needs-reader']=function(source,operator,options){
 var result=[],wiki=options.wiki;
 source(function(tiddler,title){
  if(!tiddler)return;
  var parser;
  try{parser=wiki.parseTiddler(title);}catch(_ignored){}
  if(!parser||!containsReader(parser.tree,title,title,wiki))result.push(title);
 });
 return result;
};
})();
"},"$:/plugins/huwiki/abc/transposed-layout.js":{"title":"$:/plugins/huwiki/abc/transposed-layout.js","type":"application/javascript","module-type":"library","text":"/*\
title: $:/plugins/huwiki/abc/transposed-layout.js
type: application/javascript
module-type: library
\*/
(function(){
"use strict";
var VoltaLayout=require('$:/plugins/huwiki/abc/volta-layout.js');

// ABCJS 6.7.2 exposes a *mapping* on the rendered tune's lineBreaks property.
// It is not the array of break indices accepted by the lineBreaks render option.
// Recover the original zero-based bar positions from the mapping and drawn staff.
function referenceBreaks(tune){
 var mapping=tune&&tune.lineBreaks, lines=tune&&tune.lines;
 if(!Array.isArray(mapping)||!Array.isArray(lines)||!mapping.length)return null;
 var segments=mapping.filter(function(s){return s&&s.staff===0&&s.voice===0&&Number.isInteger(s.ogLine)&&Number.isInteger(s.line);});
 if(!segments.length)return null;
 var breaks=[],current=null,bars=0,group=[],voiceGroup=[];
 for(var i=0;i<segments.length;i++){
  var segment=segments[i], next=segments[i+1];
  if(current!==segment.ogLine){
   if(current!==null)breaks.push(VoltaLayout.balance(voiceGroup,group));
   if(current!==null&&segment.ogLine<=current)return null;
   current=segment.ogLine;bars=0;group=[];voiceGroup=[];
  }
  var line=lines[segment.line],voice=line&&line.staff&&line.staff[0]&&line.staff[0].voices&&line.staff[0].voices[0];
  if(!Array.isArray(voice))return null;
  voiceGroup=voiceGroup.concat(voice);
  for(var j=0;j<voice.length;j++)if(voice[j]&&voice[j].el_type==="bar")bars++;
  // Each mapped segment ends with a bar, except the last one of a source line.
  if(next&&next.ogLine===current){
   if(bars<1)return null;
   group.push(bars-1);
  }
 }
 breaks.push(VoltaLayout.balance(voiceGroup,group));
 return breaks;
}

// Keep the concert version's system/measure breaks for written B-flat/E-flat
// instruments. No ABC source, sounding pitches, or playback settings change.
function options(ABC,host,source,original){
 var transposition=Number(original&&original.visualTranspose)||0;
 var hasTabs=original&&original.tablature&&original.tablature.length;
 var hasSecondEnding=/(?:\[|\|)\s*2(?:[\],\s-]|$)/.test(source);
 if((!transposition&&!hasTabs&&!hasSecondEnding)||!original.wrap||original.lineBreaks||!ABC||typeof ABC.renderAbc!=="function"||!host)return original;
 var doc=host.ownerDocument||(typeof document!=="undefined"?document:null);
 if(!doc||!doc.createElement||!host.appendChild)return original;
 var sample=doc.createElement("div");
 sample.className="huwabc-concert-layout-reference";
 // display:none would make the renderer's width measurements unreliable.
 sample.style.cssText="position:absolute;left:-100000px;top:0;width:"+
  (Number(original.staffwidth)||720)+"px;visibility:hidden;pointer-events:none;";
 host.appendChild(sample);
 try{
  var baseline=Object.assign({},original,{visualTranspose:0});
  delete baseline.clickListener;
  baseline.tablature=[];
  if(hasTabs)baseline.afterParsing=function(tune){if(original.afterParsing)original.afterParsing(tune);delete tune.tablatures;};
  var rendered=ABC.renderAbc(sample,source,baseline);
  var reference=referenceBreaks(rendered&&rendered[0]);
  if(!reference)return original;
  var fixed=Object.assign({},original,{lineBreaks:reference});
  delete fixed.wrap;
  return fixed;
 }catch(error){
  // Optional reference render must not prevent a readable transposed score.
  return original;
 }finally{
  if(sample.parentNode)sample.parentNode.removeChild(sample);
 }
}
exports.options=options;
exports.referenceBreaks=referenceBreaks;
})();
"},"$:/plugins/huwiki/abc/ReaderMode":{"title":"$:/plugins/huwiki/abc/ReaderMode","type":"text/css","tags":"$:/tags/Stylesheet","text":"/* Musicians' reading view: the score owns the screen, without altering ABC
   notation, audio or TiddlyWiki's normal editor. Only the active score changes. */
@media screen {
 .huwabc-fullscreen-surface.huwabc-fullscreen-surface.huwabc-fullscreen-surface{
  position:fixed!important;inset:0!important;width:100vw!important;
  height:100vh!important;height:100dvh!important;max-width:none!important;
  max-height:none!important;margin:0!important;box-sizing:border-box!important;
  isolation:isolate;
 }
 .huwabc-fullscreen-surface{z-index:10040!important}
 .huwabc-fullscreen-surface:fullscreen{width:100%!important;height:100%!important}
 .huwabc-fullscreen-surface:-webkit-full-screen{width:100%!important;height:100%!important}
}
.huwabc-reader-toolbar[hidden],
.huwabc-reader-edges[hidden],
.huwabc-reader-menu-panel[hidden]{display:none!important}
.huwabc-score.huwabc-reader-active{
 position:fixed!important;
 inset:0!important;
 box-sizing:border-box!important;
 width:100vw!important;
 max-width:none!important;
 height:100dvh!important;
 min-height:0!important;
 margin:0!important;
 padding:0!important;
 border:0!important;
 border-radius:0!important;
 display:flex!important;
 flex-direction:column!important;
 overflow:hidden!important;
 z-index:30100!important;
 color:#202521!important;
 background:#ebeeea!important
}
