 Object.keys(row).forEach(function(k){if((k.indexOf('abc-')===0&&!/^abc-(?:origin-library|origin-entry)$/.test(k))||['source-url','repertoire-sheet-format','repertoire-abc-label','repertoire-category'].indexOf(k)>=0)out[k]=row[k];});
