'use strict';
const data=require('$:/plugins/huwiki/music/data.js');
exports['huwiki-music-kind']=function(source,operator){const out=[];source((t,title)=>{if(data.kinds(t).includes(operator.operand))out.push(title);});return out;};
exports['huwiki-music-template']=function(source){const out=[];source(t=>{if(data.viewEligible(t))out.push('$:/plugins/huwiki/music/View');});return out;};
exports['huwiki-music-auto-score']=function(source){const out=[];source((t,title)=>{if(data.autoScore(t))out.push(title);});return out;};
"},"$:/plugins/huwiki/music/editor-operation.js":{"title":"$:/plugins/huwiki/music/editor-operation.js","type":"application/javascript","module-type":"texteditoroperation","text":"/*\
