}
@supports not (container-type:inline-size){
 @media(max-width:1100px){.huwrep-stand-layout{grid-template-columns:1fr}}
 @media(max-width:650px){.huwrep-editor-fields{grid-template-columns:1fr}}
}
@media print{
 .huwrep-order-handle,.huwrep-order-remove{display:none!important}
 .huwrep-stand-layout{display:block}
}

/* Repertoire Nodebog – responsive reader, one ABC score loaded at a time. */
/* An editor suspends the book; its author display:flex must not override HTML hidden. */
.huwrep-book[hidden]{display:none!important}
.huwrep-book{position:relative;display:flex;flex-direction:column;gap:0;min-height:70vh;border:1px solid #c6d9d0;border-radius:10px;overflow:hidden;background:#f6faf7;color:#183c31;font:inherit}
.huwrep-book-header{position:relative;z-index:2;display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:8px;border-bottom:1px solid #d6e5dc;background:#edf5f0}
.huwrep-book-header>.huwrep-input{width:auto;flex:1 1 170px;max-width:100%}
.huwrep-book-heading{display:flex;align-items:baseline;justify-content:space-between;gap:10px;padding:8px 12px}
.huwrep-book-heading h2{margin:0;font-size:1.2em;line-height:1.3}
.huwrep-book-list{margin:0 8px 6px;padding:6px 8px;border:1px solid #d2e3d9;border-radius:7px;background:white}
.huwrep-book-list>summary{cursor:pointer;min-height:24px}
.huwrep-book-list-items{display:flex;flex-wrap:wrap;max-height:28vh;overflow:auto;gap:5px;padding:9px 0}
.huwrep-book-agreement{display:flex;flex-wrap:wrap;gap:8px;padding:6px 12px;font-size:0.9em;background:#e9f2e9}
.huwrep-book-agreement>span{border-left:2px solid #437a60;padding-left:7px}
.huwrep-book-transform-error{color:#963a2f!important;border-left-color:#963a2f!important}
.huwrep-book-form{max-width:100%;white-space:pre-wrap}
.huwrep-book-stage{display:flex;align-items:flex-start;justify-content:center;min-height:45vh;overflow:auto;background:#e7ece8;position:relative}
.huwrep-book-score{width:100%;min-width:0}
.huwrep-book-score .huwabc-page-shell{margin:6px!important;max-width:none}
.huwrep-book-image{display:block;max-width:100%;max-height:80vh;margin:auto;object-fit:contain}
.huwrep-book-footer{display:flex;gap:6px;align-items:center;justify-content:space-between;flex-wrap:wrap;padding:8px;background:#e9f3ec;border-top:1px solid #cfddd3}
.huwrep-book-footer>.huwrep-muted{margin:auto}
.huwrep-book-one-page .huwrep-book-view,.huwrep-book-one-page .huwrep-book-mode,.huwrep-book-one-page .huwrep-book-page-turn,.huwrep-book-one-page .huwrep-book-page-status{display:none!important}
.huwrep-book-fullscreen{position:fixed!important;inset:0!important;width:100vw!important;max-width:none!important;height:100dvh!important;min-height:0!important;z-index:10040!important;margin:0!important;border:0!important;border-radius:0!important;overflow:hidden!important}
.huwrep-book-fullscreen .huwrep-book-stage{flex:1;min-height:0}
.huwrep-book-fullscreen .huwrep-book-image{max-height:100%}
.huwrep-book-fullscreen .huwabc-page-shell{margin:0!important}
@media(max-width:780px){.huwrep-book-header{gap:5px;padding:6px}.huwrep-book-header>.huwrep-input{flex-basis:calc(50% - 8px);min-height:40px}.huwrep-book-heading{padding:6px}.huwrep-book-footer{gap:4px;padding:5px}.huwrep-book-footer>.huwrep-button{flex:1 1 35%;min-height:42px}}
@media print{.huwrep-book-header,.huwrep-book-list,.huwrep-book-footer{display:none!important}.huwrep-book{overflow:visible;border:0}.huwrep-book-stage{overflow:visible}}

/* Nodebog: discreet floating number drawer rather than a second score view. */
.huwrep-book-list[hidden]{display:none!important}
.huwrep-book-list{position:absolute;z-index:60;top:55px;right:8px;width:min(360px,calc(100% - 16px));max-height:min(78vh,740px);overflow:auto;box-sizing:border-box;box-shadow:0 12px 36px #122d2670;background:#fff;border:1px solid #a5c1b5;border-radius:9px;margin:0;padding:10px}
.huwrep-book-list-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px}
.huwrep-book-list-search{margin-bottom:8px}
.huwrep-book-list-items{display:flex;flex-direction:column;flex-wrap:nowrap;gap:4px;max-height:min(60vh,600px);overflow:auto;padding:0}
.huwrep-book-list-items>.huwrep-button{flex:none;min-height:42px;width:100%;white-space:normal;text-align:left}
.huwrep-book-list-items>.huwrep-button[hidden]{display:none!important}
.huwrep-book-practice{padding:6px 12px;border-bottom:1px solid #c9dace;background:#f4f8ee}
.huwrep-book-practice>summary{cursor:pointer;font-weight:650;list-style:revert;min-height:32px}
.huwrep-book-practice-controls{display:flex;flex-wrap:wrap;align-items:center;gap:12px;padding:8px 0}
.huwrep-book-practice-check{display:flex;align-items:center;gap:5px;min-height:40px}
.huwrep-book-practice-check input{width:20px;height:20px}
.huwrep-book-practice-voice{flex:1 1 250px;display:flex;flex-direction:column;gap:4px;font-size:.9em;font-weight:600}
.huwrep-book-practice-voice .huwrep-input{width:100%}
.huwrep-book-practice-controls>.huwrep-muted{flex:1 1 100%;margin:2px 0;font-size:.86em}
@media(max-width:760px){
 .huwrep-book-list{top:70px;max-height:72vh}
 .huwrep-book-practice-controls{gap:7px}
 .huwrep-book-header .huwrep-book-select{max-width:100%}
}

/* No double music stand: the repertoire book itself owns the immersive stage. */
.huwrep-book .huwabc-page-desk{display:none!important}

/* Hide unloaded iPad reader while the native editor owns the song. */
.huwrep-book[hidden]{display:none!important}
.huwrep-book-print-menu{position:relative;z-index:70;flex:0 0 auto}
.huwrep-book-print-menu>summary{list-style:none;cursor:pointer;border:1px solid #91b29d;border-radius:7px;padding:9px 12px;background:#fff;font-weight:650;min-height:42px;box-sizing:border-box}
.huwrep-book-print-menu>summary::-webkit-details-marker{display:none}
.huwrep-book-print-actions{position:absolute;z-index:75;top:calc(100% + 4px);left:0;display:flex;flex-direction:column;gap:5px;min-width:min(290px,85vw);padding:8px;background:#fff;border:1px solid #b3cbbd;border-radius:9px;box-shadow:0 12px 30px #132b2440}
.huwrep-book-print-actions button{text-align:left;white-space:normal}
@media(max-width:680px){.huwrep-book-print-actions{left:auto;right:0}}

/* One canonical title may offer original PDF pages and an editable ABC variant. */
.huwrep-library-filters{margin:.7rem 0;gap:.5rem}.huwrep-library-filters select{flex:1 1 170px}
.huwrep-song-formats{display:block;font-size:.73em;font-weight:650;color:#527463;margin-top:.3rem}
.huwrep-source-options{margin:.5rem 0;padding:.5rem;border:1px solid #cbdbd1;border-radius:6px;background:#fff}
.huwrep-source-options>summary{cursor:pointer;font-weight:650}.huwrep-source-options>.huwrep-field{margin:.6rem 0}
.huwrep-book-pdf{width:100%;min-width:0;display:flex;flex-direction:column;align-self:stretch}
.huwrep-book-pdf-frame{display:block;width:100%;height:75vh;min-height:420px;border:0;background:#dce5de}
.huwrep-book-pdf-status,.huwrep-book-pdf-link{margin:.5rem 1rem}.huwrep-book-pdf-status[hidden]{display:none!important}
.huwrep-book-fullscreen .huwrep-book-pdf{height:100%}.huwrep-book-fullscreen .huwrep-book-pdf-frame{flex:1;height:100%;min-height:0}
.huwrep-book-source{max-width:25rem}.huwrep-error{color:#9b312b}

/* One performance surface for a single piece and every folder. */
.huwrep-session[hidden],.huwrep-session [hidden]{display:none!important}
.huwrep-session .huwabc-head,.huwrep-session .huwabc-quick-settings,.huwrep-session .huwabc-settings,.huwrep-session .huwabc-learn-panels,.huwrep-session .huwabc-open-reader,.huwrep-session .huwabc-page-toolbar,.huwrep-session .huwabc-reader-toolbar,.huwrep-session .huwabc-reader-edges{display:none!important}
.huwrep-session .huwabc-score{margin:0;padding:0;border:0;box-shadow:none}
.huwrep-session .huwabc-audio{margin:0;padding:0;border:0;background:transparent;box-shadow:none}
.huwrep-session .huwabc-audio-caption{display:none}
.huwrep-session .huwabc-audio-controls{margin:0;padding:.35rem 0}
.huwrep-performance{position:relative;flex:none;padding:6px 12px;border-bottom:1px solid #cfddd3;background:#f3f8f4}
.huwrep-performance-tools{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.huwrep-audio-source{font-size:.8em;flex:1 1 240px}
.huwrep-session .huwabc-accompaniment{margin:.5rem 0;padding:.6rem;border:1px solid #c6d9d0;border-radius:8px;max-height:40dvh;overflow:auto}
.huwrep-session .huwrep-book-heading{flex-wrap:wrap}
.huwrep-session .huwrep-book-source{width:auto;max-width:100%;font-size:.86em;min-height:40px}
.huwrep-session-settings{position:relative;z-index:72;margin-left:auto}
.huwrep-session-settings>summary{display:flex;align-items:center;cursor:pointer;min-height:42px;border:1px solid #a5c1b5;border-radius:7px;padding:0 12px;background:#fff;list-style:none}
.huwrep-session-settings>summary::-webkit-details-marker{display:none}
.huwrep-session-settings-body{position:absolute;right:0;top:calc(100% + 5px);display:flex;flex-direction:column;gap:8px;width:min(370px,85vw);max-height:70dvh;overflow:auto;padding:12px;box-sizing:border-box;border:1px solid #a5c1b5;border-radius:9px;background:white;box-shadow:0 12px 32px #14251c40}
.huwrep-session-settings-body>.huwrep-input,.huwrep-session-settings-body>.huwrep-button{width:100%;text-align:left;white-space:normal}
.huwrep-session .huwrep-book-footer>.huwrep-button{flex:1 1 25%;max-width:38rem}
.huwrep-session.huwrep-book-one-page .huwrep-book-page-turn{display:block!important}
.huwrep-session .huwrep-book-practice>summary{min-height:36px;display:list-item}
.huwrep-session.huwrep-book-fullscreen .huwrep-book-stage{overflow:auto;min-height:0;flex:1}
.huwrep-session.huwrep-book-fullscreen .huwrep-book-score{height:100%}
.huwrep-session.huwrep-book-fullscreen .huwabc-page-shell{height:100%;max-height:100%;overflow:auto;box-sizing:border-box}
.huwrep-session .huwrep-book-stage{align-items:stretch}
@media(max-width:650px){.huwrep-session .huwrep-book-header{gap:5px}.huwrep-session .huwrep-book-header>.huwrep-button{font-size:.82em;padding:6px}.huwrep-session-settings>summary{font-size:.82em;padding:0 8px}.huwrep-performance{padding:5px 7px}.huwrep-session .huwrep-book-heading{gap:5px}.huwrep-session .huwrep-book-heading h2{flex:1 1 65%}.huwrep-session .huwrep-book-source{width:100%}}
@media print{.huwrep-performance,.huwrep-book-practice,.huwrep-session-settings{display:none!important}}
.huwrep-session .huwabc-settings-panel{display:none!important}
.huwrep-library{display:flex;flex-direction:column;gap:12px}
.huwrep-library [hidden]{display:none!important}
.huwrep-library-actions{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
.huwrep-library-actions button[aria-pressed=true]{background:#176b53;color:white;border-color:#176b53}
.huwrep-library-folder{display:block;width:100%;margin:7px 0;padding:14px;text-align:left;white-space:normal}
.huwrep-library-song-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:8px;margin-top:12px}
.huwrep-library-song{display:flex;flex-direction:column;align-items:flex-start;gap:7px;white-space:normal;text-align:left;padding:12px;min-height:80px}
.huwrep-library-song small{font-size:.75em;font-weight:400}
.huwrep-performance .huwabc-mixer-toggle{display:none!important}
.huwrep-style-choice{display:flex;align-items:center;gap:10px;font-weight:650;margin:0 0 10px}
.huwrep-style-choice select{flex:1;min-width:0}

/* Immersive reading uses the browser fullscreen surface when available,
   and the full visual viewport on tablets that only support inline content. */
@media screen {
 .huwrep-session.huwrep-book-fullscreen {
  width:100%!important;
  height:100vh!important;
  height:100dvh!important;
  box-sizing:border-box;
  padding:env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left);
 }
 .huwrep-session.huwrep-book-fullscreen:fullscreen,
 .huwrep-session.huwrep-book-fullscreen:-webkit-full-screen {height:100%!important}
 .huwrep-book-fullscreen .huwrep-book-header {padding:4px 8px}
 .huwrep-book-fullscreen .huwrep-book-heading {padding:2px 8px}
 .huwrep-book-fullscreen .huwrep-book-agreement,
 .huwrep-book-fullscreen .helles-reader-lyrics,
 .huwrep-book-fullscreen .huwrep-performance:has(.huwrep-sound-toggle:disabled) {display:none}
 /* The embedded viewer already has page, song and print controls. Keep the
    book's own controls and PDF link available when the frame cannot load. */
 .huwrep-book-fullscreen:has(.huwrep-book-pdf-status[hidden]) .huwrep-book-footer,
 .huwrep-book-fullscreen:has(.huwrep-book-pdf-status[hidden]) .huwrep-book-pdf-link {display:none}
}

/* Each reading surface owns its layers. Audio and native score selectors
   must never paint above the opaque display menu. */
.huwrep-session {isolation:isolate}
.huwrep-session > :is(.huwrep-book-heading,.huwrep-performance,.huwrep-book-practice,.huwrep-book-footer) {position:relative;z-index:1}
.huwrep-session > .huwrep-book-stage {z-index:0;isolation:isolate}
.huwrep-session-settings-body {z-index:1;isolation:isolate;background:#fff;opacity:1}
.huwrep-session-settings:not([open]) > .huwrep-session-settings-body {display:none!important}
@media screen {
 .huwrep-session.huwrep-book-fullscreen {z-index:30000!important;min-width:0!important;width:100vw!important;max-height:none!important}
 .huwrep-book-fullscreen .huwrep-book-stage {min-height:0!important}
}

.huwrep-book:not(.huwrep-book-fullscreen) :is(.huwrep-reading-controls,.huwrep-reading-fit) {display:none}
@media screen {
 .huwrep-session > .huwrep-book-header {z-index:100}
 .huwrep-book-fullscreen:not(.huwrep-show-reading-controls) :is(
  .huwrep-performance,.huwrep-book-practice,.huwabc-instrument-bar,
  .huwabc-instrument-group
 ) {display:none!important}
 .huwrep-book-fullscreen .huwrep-book-score > .huwabc-score {
  height:100%;display:flex;flex-direction:column;min-height:0
 }
 .huwrep-session.huwrep-book-fullscreen .huwabc-page-shell {
  display:flex;flex-direction:column;flex:1 1 auto;min-height:0;overflow:hidden
 }
 .huwrep-book-fullscreen .huwabc-page-viewport {
  flex:1 1 auto;min-height:0;max-height:none!important;overflow:auto;container-type:size
 }
 .huwrep-book-fullscreen .huwabc-page-nav {display:none!important}
 /* The printed page ratio still applies. In a landscape viewport the
    width option deliberately allows vertical scrolling to keep notes large. */
 .huwrep-book-fullscreen .huwabc-paginated {
  --huwabc-track-width:100%!important;
  --huwrep-sheet-width:calc(100% - 16px);
  --huwabc-page-width:var(--huwrep-sheet-width)!important;
 }
 .huwrep-book-fullscreen [data-pages-shown="2"] .huwabc-paginated {
  --huwrep-sheet-width:calc((100% - 32px) / 2);
 }
 @supports (height:1cqh) {
  .huwrep-book-fullscreen.huwrep-fit-whole-page .huwabc-paginated {
   --huwabc-page-width:min(var(--huwrep-sheet-width),calc((100cqh - 8px) * var(--huwabc-page-ratio)))!important;
  }
 }
}

/* A single toolbar for PDF and ABC. Secondary controls overlay the score. */
.huwrep-session > .huwrep-compact-header {flex-wrap:nowrap;gap:4px;padding:4px;min-height:44px;box-sizing:border-box}
.huwrep-compact-header > .huwrep-button,.huwrep-compact-header .huwrep-book-page-turn,
.huwrep-compact-header > .huwrep-session-settings > summary {flex:0 0 36px;min-width:36px;min-height:36px;height:36px;padding:4px;font-size:20px;text-align:center;justify-content:center;box-sizing:border-box}
.huwrep-compact-header > .huwrep-book-heading {order:1;flex:1 1 100px;min-width:0;display:block;padding:0 4px}
.huwrep-compact-header .huwrep-book-heading h2 {overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:1em;font-weight:650}
.huwrep-compact-header .huwrep-book-heading > .huwrep-muted {display:none}
.huwrep-compact-header > .huwrep-book-footer {order:3;display:flex!important;flex:none;flex-wrap:nowrap;align-items:center;gap:4px;padding:0;border:0;background:transparent}
.huwrep-compact-header .huwrep-book-footer > .huwrep-book-page-status {display:inline!important;flex:none;font-size:.72em;white-space:nowrap;margin:0}
.huwrep-compact-header > .huwrep-book-fullscreen-button {order:6}
.huwrep-compact-header > .huwrep-reading-controls {order:5;display:block!important}
.huwrep-compact-header > .huwrep-session-settings {order:7;flex:none;margin:0}
.huwrep-compact-header > .huwrep-button[aria-expanded]:not(.huwrep-reading-controls) {order:4}
.huwrep-session .huwrep-compact-transport {order:2;flex:none;display:flex;align-items:center;margin:0;padding:0}
.huwrep-compact-transport .abcjs-inline-audio {display:flex!important;flex-wrap:nowrap!important;gap:4px!important;min-height:0!important;margin:0!important;padding:0!important;background:transparent!important}
.huwrep-compact-transport .abcjs-inline-audio > :not(.abcjs-midi-start):not(.huwabc-stop) {display:none!important}
.huwrep-compact-transport > :not(.abcjs-inline-audio) {display:none!important}
.huwrep-session .huwrep-compact-transport .abcjs-midi-start {min-height:36px!important;height:36px!important;width:36px!important;min-width:36px!important;padding:6px!important;box-sizing:border-box!important}
.huwrep-compact-transport .abcjs-midi-start::after {display:none!important}
.huwrep-compact-transport .huwabc-stop {width:36px;height:36px;min-height:36px;font-size:0;padding:4px}
.huwrep-compact-transport .huwabc-stop::after {content:'■';font-size:16px}
.huwrep-session > .huwrep-performance {display:none!important;position:absolute;z-index:90;top:48px;right:4px;width:min(650px,calc(100% - 8px));max-height:calc(100dvh - 70px);overflow:auto;padding:10px;box-sizing:border-box;border:1px solid #a5c1b5;border-radius:8px;background:#f6faf7;box-shadow:0 12px 32px #14251c40;isolation:isolate}
.huwrep-session.huwrep-show-reading-controls > .huwrep-performance {display:block!important}
.huwrep-session .huwrep-performance .huwabc-instrument-bar,
.huwrep-session .huwrep-performance .huwrep-book-practice {display:flex!important;flex-wrap:wrap}
.huwrep-session .huwrep-performance .huwrep-book-practice {display:block!important;margin-top:8px}
.huwrep-session .huwrep-performance .huwabc-accompaniment {max-height:none}
.huwrep-session .huwrep-performance .huwrep-book-practice > summary {font-size:.9em}
.huwrep-performance .huwrep-audio-source {flex-basis:auto}
.huwrep-session .huwrep-session-settings-body > .huwrep-book-source {max-width:none;width:100%}
.huwrep-compact-header .huwrep-session-settings-body {max-height:calc(100dvh - 65px)}
.huwrep-session.huwrep-book-fullscreen .huwrep-compact-header {flex:0 0 auto;padding:4px;min-height:44px}
.huwrep-session.huwrep-book-fullscreen .huwrep-book-stage {flex:1 1 auto;min-height:0}
@media(max-width:600px){
 .huwrep-compact-header .huwrep-book-footer > .huwrep-book-page-status {display:none!important}
 .huwrep-compact-header > .huwrep-book-heading {flex-basis:40px}
 .huwrep-compact-header > .huwrep-button,.huwrep-compact-header .huwrep-book-page-turn,.huwrep-compact-header > .huwrep-session-settings > summary {min-width:32px;flex-basis:32px;width:32px}
 .huwrep-compact-transport .huwabc-stop {display:none!important}
}
.huwrep-compact-header > .huwrep-edit-score {order:6}
.huwrep-session .huwrep-compact-transport .abcjs-midi-start .huwabc-control-label,
.huwrep-session .huwrep-compact-transport .abcjs-midi-start .huwabc-control-label-pause {display:none!important}
.huwrep-session .huwrep-compact-transport .abcjs-midi-start {display:inline-flex!important;align-items:center!important;justify-content:center!important;gap:0!important;overflow:hidden}
.huwrep-session .huwrep-compact-transport .abcjs-midi-start .huwabc-icon {flex:none;margin:0!important}
.huwrep-session .huwrep-compact-transport .huwabc-stop {font-size:0!important}
.huwrep-session .huwrep-compact-transport .huwabc-stop::after {font-size:16px!important}
/* ABCJS reserves 260px for its full transport. The compact toolbar only needs
   the visible play/stop icons, including on a portrait iPad. */
.huwrep-session .huwrep-compact-transport .abcjs-inline-audio {width:auto!important;min-width:0!important;max-width:none!important}

/* A recording is a peer of PDF and ABC, using the same compact book header. */
.huwrep-youtube {box-sizing:border-box;width:100%;height:100%;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:.6rem;padding:.65rem;background:#101917;color:#fff;overflow:auto;}
.huwrep-youtube-frame {display:block;flex:1 1 auto;width:100%;max-width:1440px;min-height:200px;aspect-ratio:16/9;border:0;background:#000;}
.huwrep-youtube-caption {flex:0 0 auto;display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:.35rem .9rem;width:100%;max-width:1440px;text-align:center;}
.huwrep-youtube-caption p {width:100%;margin:0;}
.huwrep-youtube-caption .huwrep-muted {color:#d2ded9;}
.huwrep-youtube-caption a {background:#f4faf7;color:#173c31;}
.huwrep-video-active .huwrep-book-stage {min-height:320px;}
.huwrep-book-fullscreen.huwrep-video-active .huwrep-book-stage {min-height:0;}
.huwrep-video-active .huwrep-performance {display:none!important;}
.huwrep-video-edit label {display:block;}
.huwrep-video-edit input {width:100%;box-sizing:border-box;margin:.4rem 0;}
