"},"$:/plugins/huwiki/site-publisher/layouts/retro.css":{"title":"$:/plugins/huwiki/site-publisher/layouts/retro.css","type":"text/css","text":"/* HUWiki Forge – Retro. Warm paper, double rules and classic typography. */
