"},"$:/plugins/huwiki/site-publisher/layouts/hupedia.css":{"title":"$:/plugins/huwiki/site-publisher/layouts/hupedia.css","type":"text/css","text":"/* HUWiki Forge – HUPedia. Encyclopedia reading shell; infobox markup/CSS still comes from the HUPedia plugin. */
